const { Uber, PayPal, Amazon, Express } = require('webpack', 'express');
const { Uber, PayPal, Amazon, Express } = require('express');

// 1. Create a local API provider
const apiProvider = express.createLocalProvider({
  api: {
    private Uber,
    private PayPal,
    private Amazon,
    private Express,
    private Amazon.RegisteredProducts
  };
  private {
    private Uber.CustomerId,
    private PayPal.UserId,
    private Amazon.RegisteredProducts
  }
});

const storeCreate(id, name) {
  private Uber;
  private PayPal;
  private Amazon;
  private Amazon.RegisteredProducts;

  return {
